    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv3x3_bf16")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=32, kernel_size=3, bias=False, dtype=torch.bfloat16)

    def forward(self, x):
        if not x.is_cuda:
            raise RuntimeError("ModelNew requires CUDA tensors")
        if x.dtype is not torch.bfloat16:
            raise RuntimeError("ModelNew expects bfloat16 input")
        if x.dim() != 4 or x.shape[1] != 3:
            raise RuntimeError("ModelNew expects NCHW input with 3 channels")
        if not x.is_contiguous():
            raise RuntimeError("ModelNew expects contiguous input")
        weight = self.conv1.weight
        if not weight.is_contiguous():
            raise RuntimeError("ModelNew expects contiguous weights")

        n = x.shape[0]
        h = x.shape[2]
        w = x.shape[3]
        oh = h - 2
        ow = w - 2
        out = torch.empty((n, 32, oh, ow), dtype=torch.bfloat16, device=x.device)
        if n == 0 or oh <= 0 or ow <= 0:
            return out

        module = _get_ptx_module()
        module = _get_ptx_module()
        tiles_x = (ow + 15) // 16
        tiles_y = (oh + 15) // 16
        module.launch(
            "conv3x3_bf16",
            grid=(tiles_x * tiles_y, n, 1),
            block=(512, 1, 1),
            arguments=[x, weight, out, i32(h), i32(w), i32(oh), i32(ow)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

